using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization for high throughput on large arrays.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        ref float start = ref MemoryMarshal.GetReference(values);

        // Use 256-bit vectors (8 floats) when possible
        if (Vector256.IsHardwareAccelerated && values.Length >= Vector256<float>.Count * 2)
        {
            return FindMinMax256(ref start, values.Length);
        }

        if (Vector128.IsHardwareAccelerated && values.Length >= Vector128<float>.Count * 2)
        {
            return FindMinMax128(ref start, values.Length);
        }

        return FindMinMaxScalar(ref start, values.Length);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
    private static (float Min, float Max) FindMinMax256(ref float start, int length)
    {
        const int stride = 8; // Vector256<float>.Count
        int i = 0;

        var vMin0 = Vector256.LoadUnsafe(ref start);
        var vMax0 = vMin0;
        i += stride;

        // Unroll by 2 vectors (16 floats per iteration) to hide latency
        var vMin1 = vMin0;
        var vMax1 = vMax0;
        int limit = length - stride * 2 + 1;
        for (; i < limit; i += stride * 2)
        {
            var v0 = Vector256.LoadUnsafe(ref start, (nuint)i);
            var v1 = Vector256.LoadUnsafe(ref start, (nuint)(i + stride));
            vMin0 = Vector256.Min(vMin0, v0);
            vMax0 = Vector256.Max(vMax0, v0);
            vMin1 = Vector256.Min(vMin1, v1);
            vMax1 = Vector256.Max(vMax1, v1);
        }

        // Process remaining full vectors
        for (; i <= length - stride; i += stride)
        {
            var v = Vector256.LoadUnsafe(ref start, (nuint)i);
            vMin0 = Vector256.Min(vMin0, v);
            vMax0 = Vector256.Max(vMax0, v);
        }

        // Merge the two accumulators
        vMin0 = Vector256.Min(vMin0, vMin1);
        vMax0 = Vector256.Max(vMax0, vMax1);

        // Reduce 256 -> 128 -> scalar
        var lo = vMin0.GetLower();
        var hi = vMin0.GetUpper();
        var min128 = Vector128.Min(lo, hi);
        float min = HorizontalMin(min128);

        lo = vMax0.GetLower();
        hi = vMax0.GetUpper();
        var max128 = Vector128.Max(lo, hi);
        float max = HorizontalMax(max128);

        // Scalar tail
        for (; i < length; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
    private static (float Min, float Max) FindMinMax128(ref float start, int length)
    {
        const int stride = 4; // Vector128<float>.Count
        int i = 0;

        var vMin = Vector128.LoadUnsafe(ref start);
        var vMax = vMin;
        i += stride;

        for (; i <= length - stride; i += stride)
        {
            var v = Vector128.LoadUnsafe(ref start, (nuint)i);
            vMin = Vector128.Min(vMin, v);
            vMax = Vector128.Max(vMax, v);
        }

        float min = HorizontalMin(vMin);
        float max = HorizontalMax(vMax);

        for (; i < length; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMin(Vector128<float> v)
    {
        // Reduce 4 floats to minimum via shuffle and min
        var shuf = Vector128.Shuffle(v, Vector128.Create(2, 3, 0, 1));
        v = Vector128.Min(v, shuf);
        shuf = Vector128.Shuffle(v, Vector128.Create(1, 0, 3, 2));
        v = Vector128.Min(v, shuf);
        return v.ToScalar();
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMax(Vector128<float> v)
    {
        var shuf = Vector128.Shuffle(v, Vector128.Create(2, 3, 0, 1));
        v = Vector128.Max(v, shuf);
        shuf = Vector128.Shuffle(v, Vector128.Create(1, 0, 3, 2));
        v = Vector128.Max(v, shuf);
        return v.ToScalar();
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static (float Min, float Max) FindMinMaxScalar(ref float start, int length)
    {
        float min = start;
        float max = start;
        for (int i = 1; i < length; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }
